using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing.Editor {
public static class RaceAiVerification {
 static readonly List<string> checks=new List<string>();static void Check(bool ok,string text){checks.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines("Verification/RaceAi/rules.txt",checks);if(!ok)throw new Exception(text);}
 static Vector3[] Straight(){var p=new List<Vector3>();for(int i=0;i<=300;i++)p.Add(new Vector3(0,0,i*4));for(int i=1;i<=10;i++)p.Add(new Vector3(i*4,0,1200));for(int i=299;i>=0;i--)p.Add(new Vector3(40,0,i*4));for(int i=9;i>=1;i--)p.Add(new Vector3(i*4,0,0));return p.ToArray();}
 static RoadPilot Agent(string name,int index,float cruise,bool rival,float lane=1.75f){var car=TrafficWorld.CreateCar(name,new WorkshopBuild(),0);var p=car.gameObject.AddComponent<RoadPilot>();p.Car=car;p.Path=Straight();p.Index=index;p.IsRival=rival;p.CruiseKph=cruise;p.Lane=lane;p.Place(index);return p;}
 static void Step(params RoadPilot[] pilots){foreach(var p in pilots){p.Drive(.02f);p.Car.Tick(.02f);}Physics.Simulate(.02f);}
 static void Destroy(params RoadPilot[] pilots){foreach(var p in pilots)UnityEngine.Object.DestroyImmediate(p.gameObject);TrafficWorld.Agents.Clear();}
 public static void Run(){Directory.CreateDirectory("Verification/RaceAi");checks.Clear();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.5f,600);floor.transform.localScale=new Vector3(100,1,1400);var previous=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{
 var rival=Agent("Full power rival",20,90,true);Physics.SyncTransforms();rival.Drive(.02f);Check(rival.Car.commandedPedal==1&&rival.Car.commandedServiceBrake==0,"Rival requests exactly full throttle on open straight without artificial95percent cap");for(int i=0;i<700;i++)Step(rival);Check(rival.Car.SpeedKph>70,"Actual stock rival accelerates beyond70kmh under wheel physics");Check(rival.Car.GetComponentsInChildren<WheelCollider>().Length==4,"Planner retains four contacts and original engine/handling physics");Destroy(rival);
 rival=Agent("Passing rival",20,85,true);var slow=Agent("Slow lane traffic",27,28,false);Physics.SyncTransforms();float nearest=100,maxOffset=0;bool passed=false;for(int i=0;i<2500;i++){Step(rival,slow);nearest=Mathf.Min(nearest,Vector3.Distance(rival.transform.position,slow.transform.position));maxOffset=Mathf.Max(maxOffset,Mathf.Abs(rival.LaneShift));if(rival.Overtakes>0&&!rival.Passing&&Mathf.Abs(rival.LaneShift)<.1f){passed=true;break;}}File.WriteAllText("Verification/RaceAi/passing-measurements.txt","passed="+passed+" overtake="+rival.Overtakes+" nearest="+nearest+" offset="+maxOffset+" pos="+rival.transform.position+" slow="+slow.transform.position+" speed="+rival.Car.SpeedKph);
 Check(maxOffset>3,"Rival selects clear adjacent lane around slower physical traffic");Check(passed&&rival.transform.position.z>slow.transform.position.z+8,"Actual wheel-driven rival passes slow car and merges back ahead");Check(nearest>2.1f&&rival.Recoveries==0,"Ordinary pass maintains physical separation without teleport recovery");Destroy(rival,slow);
 rival=Agent("Safe waiting rival",20,85,true);slow=Agent("Stopped leader",26,0,false);slow.Held=true;var oncoming=Agent("Occupied passing lane",40,0,false,-1.75f);oncoming.Car.ResetAt(new Vector3(-1.75f,.35f,160),Quaternion.Euler(0,180,0));oncoming.Held=true;Physics.SyncTransforms();float closest=100,offset=0;for(int i=0;i<700;i++){Step(rival,slow,oncoming);closest=Mathf.Min(closest,Vector3.Distance(rival.transform.position,slow.transform.position));offset=Mathf.Max(offset,Mathf.Abs(rival.LaneShift));}Check(offset<.05f&&rival.Overtakes==0,"Rival waits when opposing lane is occupied rather than forcing a pass");Check(closest>4&&rival.Car.SpeedKph<3,"Stopped traffic produces real braking and safe stationary gap");Destroy(rival,slow,oncoming);
 rival=Agent("Closing-speed safety",20,85,true);slow=Agent("Slow leader",27,28,false);oncoming=Agent("Fast oncoming car",75,0,false,-1.75f);oncoming.Car.ResetAt(new Vector3(-1.75f,.35f,300),Quaternion.Euler(0,180,0));oncoming.Car.Body.linearVelocity=Vector3.back*30;Physics.SyncTransforms();for(int i=0;i<30;i++)rival.Drive(.02f);Check(!rival.Passing&&Mathf.Abs(rival.LaneShift)<.05f,"Pass safety predicts closing speed using intended acceleration, not only current low speed");Destroy(rival,slow,oncoming);
 rival=Agent("Wrong-side route fixture",20,85,true,-1.75f);slow=Agent("Wrong-side leader",26,0,false,-1.75f);Physics.SyncTransforms();for(int i=0;i<40;i++)rival.Drive(.02f);Check(!rival.Passing,"Passing is confined to right-hand travel lane and never creates off-road third lane");Destroy(rival,slow);
 rival=Agent("Corner planner",20,115,true);var path=new List<Vector3>();for(int i=0;i<60;i++)path.Add(new Vector3(0,0,i*4));for(int i=1;i<=60;i++){float a=i*Mathf.PI/120;path.Add(new Vector3(30-30*Mathf.Cos(a),0,236+30*Mathf.Sin(a)));}rival.Path=path.ToArray();rival.Index=48;rival.Car.ResetAt(new Vector3(1.75f,.35f,192),Quaternion.identity);rival.Car.Body.linearVelocity=Vector3.forward*25;Physics.SyncTransforms();rival.Drive(.02f);Check(rival.TargetKph<100&&rival.TargetKph>20,"Speed planner anticipates tight bend using radius and braking distance");Destroy(rival);
 }finally{Physics.simulationMode=previous;UnityEngine.Object.DestroyImmediate(floor);} }
 public static void Release(){Run();RaceAiCityVerification.Run();InventoryVerification.CheckExistingAssets();ModelDrivingVerification.Run();HarborValeGreybox.Workshop.Editor.AvCameraVerification.Run();HarborValeGreybox.Workshop.Editor.TurboAudioVerification.Run();HarborValeGreybox.Presentation.Editor.CityArtVerification.Release();}
}
}
